import json

def dispatch(call, tools):
    name = call.get("name")
    if name not in tools:
        return {"ok": False, "error": f"unknown tool: {name}"}
    args = call.get("arguments", {})
    if isinstance(args, str):
        try:
            args = json.loads(args)
        except json.JSONDecodeError:
            return {"ok": False, "error": "invalid json"}
    try:
        result = tools[name](**args)
    except TypeError:
        return {"ok": False, "error": "bad arguments"}
    return {"ok": True, "result": result}

def run_agent(model, tools, task, max_steps):
    history = [{"role": "user", "content": task}]
    for _ in range(max_steps):
        decision = model(history)
        if decision["action"] == "final":
            return decision["answer"]
        name = decision["name"]
        if name in tools:
            content = tools[name](**decision.get("args", {}))
        else:
            content = "error: unknown tool"
        history.append({"role": "tool", "name": name, "content": content})
    return "stopped: max steps"

