import math

def forward_kinematics(l1, l2, theta1_deg, theta2_deg):
    t1 = math.radians(theta1_deg)
    t12 = math.radians(theta1_deg + theta2_deg)
    return (l1 * math.cos(t1) + l2 * math.cos(t12), l1 * math.sin(t1) + l2 * math.sin(t12))

def inverse_kinematics(l1, l2, x, y):
    c2 = (x * x + y * y - l1 * l1 - l2 * l2) / (2 * l1 * l2)
    if c2 > 1 + 1e-9 or c2 < -1 - 1e-9:
        return None
    c2 = max(-1.0, min(1.0, c2))
    t2 = math.acos(c2)
    t1 = math.atan2(y, x) - math.atan2(l2 * math.sin(t2), l1 + l2 * math.cos(t2))
    return (math.degrees(t1), math.degrees(t2))

