import random

# Corridor with 5 cells: 0 1 2 3 4. Cell 4 is the goal.
# Actions: 0 = left, 1 = right.
N_STATES = 5


def step(s, a):
    s2 = max(0, s - 1) if a == 0 else min(N_STATES - 1, s + 1)
    if s2 == N_STATES - 1:
        return s2, 1.0, True
    return s2, 0.0, False


def q_update(Q, s, a, r, s2, done, alpha, gamma):
    target = r if done else r + gamma * max(Q[s2])
    Q[s][a] = Q[s][a] + alpha * (target - Q[s][a])


def greedy_action(Q, s):
    return 0 if Q[s][0] >= Q[s][1] else 1


def train(episodes=200, alpha=0.5, gamma=0.9, epsilon=0.2, seed=0):
    rng = random.Random(seed)
    Q = [[0.0, 0.0] for _ in range(N_STATES)]
    for _ in range(episodes):
        s = 0
        for _ in range(50):
            if rng.random() < epsilon or Q[s][0] == Q[s][1]:
                a = rng.randrange(2)
            else:
                a = greedy_action(Q, s)
            s2, r, done = step(s, a)
            q_update(Q, s, a, r, s2, done, alpha, gamma)
            s = s2
            if done:
                break
    return Q
